// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    CountingToken token;

    function setUp() public {
        c = new C();
        token = new CountingToken();
    }

    function testFuzz_property(address from, address[] memory tos, uint[] memory vals) public {
        vm.assume(tos.length == 2);
        vm.assume(vals.length == 2);
        vm.assume(tos[0] != address(0));
        vm.assume(tos[1] != address(0));
        c.transfer(from, address(token), tos, vals);
        // General rule: every recipient gets a transferFrom call, i.e. exactly tos.length calls.
        assertTrue(token.calls() == tos.length);
    }
}

contract CountingToken {
    uint256 public calls;
    fallback(bytes calldata) external payable returns (bytes memory) {
        calls++;
        return abi.encode(true);
    }
}
